import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const u=JSON.parse('{"title":"Who Called Privacy Policy","description":"Official Privacy Policy for Who Called.","frontmatter":{"title":"Who Called Privacy Policy","description":"Official Privacy Policy for Who Called.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/who-called.md","filePath":"privacy/who-called.md"}'),n={name:"privacy/who-called.md"};function i(s,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy-for-who-called" tabindex="-1">Privacy Policy for Who Called <a class="header-anchor" href="#privacy-policy-for-who-called" aria-label="Permalink to &quot;Privacy Policy for Who Called&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 3, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Who Called is an offline-first private contact organizer developed by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Who Called stores records encrypted with AES-256-GCM in local IndexedDB. These records can include:</p><ul><li>Private contact names, companies, phone numbers, email addresses, social links, birth dates, up to three named anniversary dates, reminder choices, notes, favourites, hidden status, and WhatsApp preferences</li><li>Saved messages that you manually enter, paste, or share to the app, including titles, senders, categories, detected codes, favourites, and saved bold or highlight formatting ranges</li><li>Tags and notes for unknown numbers, appearance counts, and last-seen dates</li><li>Country, theme, privacy, call-history, security, and other app settings</li></ul><p>The encryption key is a non-extractable browser CryptoKey stored locally in IndexedDB. The developer does not receive the database or encryption key. Who Called does not store application records in localStorage, sessionStorage, or cookies.</p><h2 id="android-call-log-permission-and-recent-calls" tabindex="-1">Android Call Log Permission and Recent Calls <a class="header-anchor" href="#android-call-log-permission-and-recent-calls" aria-label="Permalink to &quot;Android Call Log Permission and Recent Calls&quot;">​</a></h2><p>The released Android app declares and requests <code>android.permission.READ_CALL_LOG</code>. This permission is used only to show the phone&#39;s recent call history on the Who Called homepage and to match those calls locally against private contacts or tagged numbers in the app.</p><p>Who Called reads at most the 100 most recent call-log entries after you enable the feature and grant Android&#39;s runtime permission. For each entry, the app can read the phone number, cached caller name when available, call type (such as incoming, outgoing, missed, rejected, blocked, or voicemail), date and time, and call duration.</p><p>The retrieved call-history list is processed on the device and held temporarily for the current app session. It is not written to Who Called&#39;s database, backups, CSV files, or vCard files, and it is not transmitted to the developer or a developer-operated server. Disabling the setting stops future retrieval. Android controls the permission, and denying or revoking it leaves the rest of the app available.</p><p><code>READ_CALL_LOG</code> does not give Who Called access to SMS content. Who Called does not request an SMS-reading permission and does not read the SMS inbox, sent messages, one-time passwords from SMS, or MMS content. It also does not read Android Contacts, notification content, or recorded call audio.</p><h2 id="optional-birthday-and-anniversary-reminders" tabindex="-1">Optional Birthday and Anniversary Reminders <a class="header-anchor" href="#optional-birthday-and-anniversary-reminders" aria-label="Permalink to &quot;Optional Birthday and Anniversary Reminders&quot;">​</a></h2><p>On Android, you can optionally schedule a birthday or anniversary reminder for a contact. The app requests notification permission only when you enable a reminder. Enabled reminders are scheduled locally through Android to repeat yearly at approximately 6:00 AM.</p><p>A reminder can display the contact&#39;s name and the birthday or named anniversary in an Android notification. Android controls notification delivery, lock-screen visibility, and timing. Reminder schedules and preferences are not sent to the developer. Web builds retain reminder choices in the encrypted local record but do not display browser notifications.</p><h2 id="calling-sms-whatsapp-and-web-links" tabindex="-1">Calling, SMS, WhatsApp, and Web Links <a class="header-anchor" href="#calling-sms-whatsapp-and-web-links" aria-label="Permalink to &quot;Calling, SMS, WhatsApp, and Web Links&quot;">​</a></h2><p>Who Called can pass a phone number to the Android dialer, pass a number and draft text to the SMS composer, or open a WhatsApp or WhatsApp Business chat using a <code>wa.me</code> link. These actions occur only after your request. The app does not silently place a call or send a message.</p><p>Web addresses detected inside a saved message become actionable only within that message view. Who Called shows a confirmation before passing the selected address to your browser. You can cancel or copy the address instead.</p><p>The selected external app receives the phone number and any draft message you provide. WhatsApp, your carrier, phone app, SMS app, browser, and other handlers process information under their own privacy practices.</p><h2 id="shared-text-and-clipboard" tabindex="-1">Shared Text and Clipboard <a class="header-anchor" href="#shared-text-and-clipboard" aria-label="Permalink to &quot;Shared Text and Clipboard&quot;">​</a></h2><p>On Android, Who Called can receive plain text you explicitly share from another app. It displays that text in the Saved Message editor for review and does not save it automatically. Clipboard content is read only when you choose a paste action and is written only when you choose a copy action.</p><h2 id="app-lock-biometrics-and-screenshots" tabindex="-1">App Lock, Biometrics, and Screenshots <a class="header-anchor" href="#app-lock-biometrics-and-screenshots" aria-label="Permalink to &quot;App Lock, Biometrics, and Screenshots&quot;">​</a></h2><p>If you enable an application PIN, Who Called stores a salted PBKDF2-SHA-256 verifier rather than the PIN itself. Optional Android biometric unlock uses Android BiometricPrompt and Android Keystore. Who Called does not receive or store biometric templates.</p><p>Optional screenshot protection asks Android to block screenshots and screen recording of the app where supported. These controls are not a replacement for device encryption or a secure device lock.</p><h2 id="backup-restore-import-and-export" tabindex="-1">Backup, Restore, Import, and Export <a class="header-anchor" href="#backup-restore-import-and-export" aria-label="Permalink to &quot;Backup, Restore, Import, and Export&quot;">​</a></h2><p>Encrypted <code>.contactvault</code> backups can include contacts, saved messages, tagged numbers, and settings. Backups use AES-256-GCM with a key derived from your passphrase using PBKDF2-SHA-256. The passphrase is not stored and cannot be recovered by the developer.</p><p>CSV and vCard contact exports are not encrypted and can contain readable contact information. Imported CSV and vCard files are read only after you select them. Files saved or shared outside Who Called are handled by the destination you choose.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>The developer does not receive contacts, call history, user-saved text, tagged numbers, PINs, backup passphrases, device identifiers, or usage telemetry. Who Called does not sell user information. References to saved messages in this policy mean text that a user manually enters, pastes, or explicitly shares to Who Called; they do not mean messages read from the SMS inbox.</p><p>If you email support, the developer receives only the information you choose to include and uses it to respond. Do not email PINs, private contact collections, saved messages, call logs, or backup files.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the Android build and features you choose, Who Called may use:</p><ul><li><code>android.permission.READ_CALL_LOG</code> to display up to 100 recent calls on the homepage after the user enables the feature and grants permission</li><li>Biometric authentication for optional app unlock</li><li>Notification access for optional birthday and anniversary reminders</li><li>File or document access for backup, restore, contact import, and export</li><li>Clipboard access for explicit paste and copy actions</li><li>Package visibility to offer installed WhatsApp or WhatsApp Business handlers</li><li>Android&#39;s share target for text you deliberately send to the app</li></ul><p>The reviewed app does not request permission to read SMS or MMS content and does not require Android Contacts, location, microphone, or phone-call placement permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Contacts moved to Trash remain encrypted locally for up to 30 days unless you restore or permanently delete them sooner. Expired trashed contacts are removed when the app loads. Saved messages and tagged numbers remain until deleted. Trashing or permanently deleting a contact cancels that contact&#39;s scheduled birthday and anniversary reminders; restoring the contact reschedules reminders that remain enabled.</p><p>Clearing app/site storage or uninstalling removes the local database. It does not remove backups, CSV files, or vCard files saved or shared elsewhere. Delete those copies separately. There is no developer-operated account or cloud database to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Who Called is not designed to collect children&#39;s personal information through a developer-operated service.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when the app&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',44)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
